async function authenticate(req,c=pool,locked=false){const raw=req.headers.get('cookie')?.match(/(?:^|;\s*)sw_session=([a-f0-9]{64})(?:;|$)/)?.[1];if(!raw)fail(401,'PLAYER_LOGIN_REQUIRED');
const r=await c.query(`SELECT u.id,u.role,u.status FROM sw_rebuild.sessions s JOIN sw_rebuild.users u ON u.id=s.user_id WHERE s.token=ANY($1::text[]) AND s.expires>$2${locked?' FOR SHARE OF s,u':''}`,[[raw,hash(raw)],Date.now()]);
if(r.rowCount!==1||r.rows[0].role!=='player'||r.rows[0].status!=='active')fail(401,'ACTIVE_PLAYER_SESSION_REQUIRED');return r.rows[0].id;}
